                    (Value::Integer(l), Value::Integer(r)) => Value::Integer(l * r).into(),
                    (Value::Integer(l), Value::Float(r)) => Value::Float((l as f64) * r).into(),
                    (Value::Float(l), Value::Integer(r)) => Value::Float(l * (r as f64)).into(),
                    (Value::Float(l), Value::Float(r)) => Value::Float(l * r).into(),
                    (l, r) => Multiply(l.into(), r.into()),
                }
            }
            Divide(l, r) => {
                let l = self.fold(*l)?;
                let r = self.fold(*r)?;
                match (l.evaluate(None)?, r.evaluate(None)?) {
                    (Value::Integer(l), Value::Integer(r)) if r != 0 => Value::Integer(l / r).into(),
                    (Value::Integer(l), Value::Float(r)) if r != 0.0 => Value::Float((l as f64) / r).into(),
                    (Value::Float(l), Value::Integer(r)) if r != 0 => Value::Float(l / (r as f64)).into(),
                    (Value::Float(l), Value::Float(r)) if r != 0.0 => Value::Float(l / r).into(),
                    (l, r) => Divide(l.into(), r.into()),
                }
            }
            Remainder(l, r) => {
                let l = self.fold(*l)?;
                let r = self.fold(*r)?;
                match (l.evaluate(None)?, r.evaluate(None)?) {
                    (Value::Integer(l), Value::Integer(r)) if r != 0 => Value::Integer(l % r).into(),
                    (Value::Integer(l), Value::Float(r)) if r != 0.0 => Value::Float((l as f64) % r).into(),
                    (Value::Float(l), Value::Integer(r)) if r != 0 => Value::Float(l % (r as f64)).into(),
                    (Value::Float(l), Value::Float(r)) if r != 0.0 => Value::Float(l % r).into(),
                    (l, r) => Remainder(l.into(), r.into()),
                }
            }
            Exponentiate(l, r) => {
                let l = self.fold(*l)?;
                let r = self.fold(*r)?;
                match (l.evaluate(None)?, r.evaluate(None)?) {
                    (Value::Integer(l), Value::Integer(r)) if r >= 0 => {
                        let r = r.try_into().map_err(|_| errinput!("integer overflow"))?;
                        Value::Integer(l.pow(r)).into()
                    }
                    (Value::Integer(l), Value::Float(r)) => Value::Float((l as f64).powf(r)).into(),
                    (Value::Float(l), Value::Integer(r)) => Value::Float(l.powi(r as i32)).into(),
                    (Value::Float(l), Value::Float(r)) => Value::Float(l.powf(r)).into(),
                    (l, r) => Exponentiate(l.into(), r.into()),
                }
            }
            Negate(e) => {
                let e = self.fold(*e)?;
                match e.evaluate(None)? {
                    Value::Integer(i) => Value::Integer(-i).into(),
                    Value::Float(f) => Value::Float(-f).into(),
                    v => Negate(v.into()),
                }
            }
            Identity(e) => {
                let e = self.fold(*e)?;
                match e.evaluate(None)? {
                    v @ (Value::Integer(_) | Value::Float(_)) => v.into(),
                    Value::Null => Value::Null.into(),
                    v => Identity(v.into()),
                }
            }
            Factorial(e) => {
                let e = self.fold(*e)?;
                match e.evaluate(None)? {
                    Value::Integer(i @ 0..) => {
                        let result = (1..=i).try_fold(Value::Integer(1), |p, i| p.checked_mul(&Value::Integer(i)))?;
                        result.into()
                    }
                    v => Factorial(v.into()),
                }
            }
            Constant(v) => Constant(v),
            Column(i) => Column(i),
            Not(e) => {
                let e = self.fold(*e)?;
                match e.evaluate(None)? {
                    Value::Boolean(b) => Value::Boolean(!b).into(),
                    v => Not(v.into()),
                }
            }
            Is(e, v) => {
                let e = self.fold(*e)?;
                Is(e.into(), v)
            }
            Like(l, r) => {
                let l = self.fold(*l)?;
                let r = self.fold(*r)?;
                Like(l.into(), r.into())
            }
            SquareRoot(e) => {
                let e = self.fold(*e)?;
                match e.evaluate(None)? {
                    Value::Integer(i @ 0..) => Value::Float((i as f64).sqrt()).into(),
                    Value::Float(f) => Value::Float(f.sqrt()).into(),
                    Value::Null => Value::Null.into(),
                    v => SquareRoot(v.into()),
                }
            }
        })
    }
}
